+    private static boolean isCloseToDetectedHeaderOrFooter(List<IObject> pageContents, int candidateIndex,
+                                                           int currentIndex, boolean isHeaderDetection) {
+        if (currentIndex == 0) {
+            return true;
+        }
+        int previousIndex = isHeaderDetection ? candidateIndex - 1 : candidateIndex + 1;
+        if (previousIndex < 0 || previousIndex >= pageContents.size()) {
+            return true;
+        }
+        IObject candidate = pageContents.get(candidateIndex);
+        IObject previous = pageContents.get(previousIndex);
+        BoundingBox candidateBoundingBox = candidate.getBoundingBox();
+        BoundingBox previousBoundingBox = previous.getBoundingBox();
+        if (candidateBoundingBox == null || previousBoundingBox == null) {
+            return true;
+        }
+
+        double gap = isHeaderDetection ? previous.getBottomY() - candidate.getTopY() :
+            candidate.getBottomY() - previous.getTopY();
+        if (gap <= 0) {
+            return true;
+        }
+
+        double maxContentHeight = Math.max(getContentHeight(candidateBoundingBox), getContentHeight(previousBoundingBox));
+        return gap <= maxContentHeight * MAX_HEADER_FOOTER_LINE_GAP_MULTIPLIER;
+    }
